const { SyncDAO } = require('../daos/syncDAO');
const { UserSettingsDAO } = require('../daos/userSettingsDAO');
const pool = require('../../config/db');
const SyncToken = require('../utils/syncToken');
const logger = require('../utils/logger');

const CALENDAR_PAST_DAYS = 90;
const CALENDAR_FUTURE_DAYS = 365;
const MESSAGING_PAST_DAYS = 30;

// 고속 차집합 연산 유틸
function diff(currArray, oldArray) {
  const oldSet = new Set(oldArray);
  return currArray.filter(x => !oldSet.has(x));
}

class SyncService {
  /**
   * [Core Sync] 앱 기동 및 포그라운드 전환 시 호출되는 메인 동기화 파이프라인
   */
  async pullChanges(userId, rawToken) {
    const now = new Date();

    // Time Windows 계산
    const calWindowFrom = new Date(now.getTime() - (CALENDAR_PAST_DAYS * 24 * 60 * 60 * 1000));
    const calWindowTo = new Date(now.getTime() + (CALENDAR_FUTURE_DAYS * 24 * 60 * 60 * 1000));
    const msgWindowFrom = new Date(now.getTime() - (MESSAGING_PAST_DAYS * 24 * 60 * 60 * 1000));

    // 1. 토큰 디코딩
    const prevToken = SyncToken.decode(rawToken) || { ts: 0, d_ids: [], c_ids: [] };
    const oldTsDate = prevToken.ts > 0 ? new Date(prevToken.ts * 1000) : null;

    // 2. 현재 유저의 '진짜' 권한 조회 (DB 기준)
    const [currDIds, currCIds] = await Promise.all([
      SyncDAO.getBinderIdsByUserId(pool, userId),
      SyncDAO.getSubscribedCalIdsByUserId(pool, userId),
    ]);

    if (!currDIds.length && !currCIds.length) {
      return this._buildEmptyResponse(now, currDIds, currCIds);
    }

    // 3. Sync Context (상태 Diff) 객체 생성 - 이 객체 하나로 모든 DAO 쿼리가 동작합니다.
    const ctx = {
      userId,
      oldTs: oldTsDate,
      oldDIds: prevToken.d_ids.filter(id => currDIds.includes(id)), // 유지된 기존 바인더
      oldCIds: prevToken.c_ids.filter(id => currCIds.includes(id)), // 유지된 기존 캘린더
      newDIds: diff(currDIds, prevToken.d_ids), // 새로 가입한 바인더
      newCIds: diff(currCIds, prevToken.c_ids), // 새로 구독한 캘린더
      calWindowFrom,
      calWindowTo,
      msgWindowFrom
    };

    // 4. 병렬 데이터 패칭 (3 트랙 완벽 분리)
    const [metaData, calendarData, messagingData, personalData] = await Promise.all([
      this._fetchTrackAMeta(userId, currDIds, currCIds, oldTsDate),
      this._fetchTrackBCalendar(ctx),
      this._fetchTrackCMessaging(ctx),
      this._fetchPersonalData(userId, currDIds, oldTsDate, msgWindowFrom)
    ]);

    // 5. 다음 동기화를 위한 새 토큰 발급
    const next_sync_token = SyncToken.encode({
      ts: Math.floor(now.getTime() / 1000),
      d_ids: currDIds,
      c_ids: currCIds,
    });

    return {
      data: {
        ...metaData,
        ...calendarData,
        ...messagingData,
        ...personalData,
      },
      next_sync_token
    };
  }

  /**
   * [Contextual Fetch] 캘린더 과거/미래 무한 스크롤 시 데이터 요청
   */
  async fetchCalendarWindow(userId, startIso, endIso) {
    const startDate = new Date(startIso);
    const endDate = new Date(endIso);

    const [currDIds, currCIds] = await Promise.all([
      SyncDAO.getBinderIdsByUserId(pool, userId),
      SyncDAO.getSubscribedCalIdsByUserId(pool, userId),
    ]);

    const ctx = {
      userId,
      currDIds,
      currCIds,
      calWindowFrom: startDate,
      calWindowTo: endDate
    };

    // 토큰 갱신 없이 데이터만 리턴 (로컬 DB Backfill 용도)
    return await SyncDAO.getCalendarDataOnlyByWindow(pool, ctx);
  }

  // =========================================================================
  // PRIVATE METHODS : 도메인별 패칭 로직 (JS 필터링 제거)
  // =========================================================================

  async _fetchTrackAMeta(userId, currDIds, currCIds, oldTs) {
    // 뼈대 데이터는 ts, old/new 따지지 않고 무조건 현재 소속 기준으로 100% 덮어씌움 (FK 에러 방지)
    const [binders, binderMembers, binderPreferences, binderSettings, users, section, calendars, subscribedCals] = await Promise.all([
      SyncDAO.getBindersForSync(pool, currDIds, currCIds),
      SyncDAO.getBinderMembers(pool, currDIds),
      SyncDAO.getBinderPreferences(pool, userId, currDIds),
      SyncDAO.getBinderSettings(pool, currDIds),
      SyncDAO.getUsersForSync(pool, currDIds, oldTs),
      SyncDAO.getSection(pool, currDIds),
      SyncDAO.getCalendarsForSync(pool, currDIds, currCIds),
      SyncDAO.getSubscribedCalendarRecords(pool, currCIds)
    ]);

    return {
      binders, binder_members: binderMembers, binder_preferences: binderPreferences,
      binder_settings: binderSettings, users, section, calendars,
      subscribed_calendars: subscribedCals
    };
  }

  async _fetchTrackBCalendar(ctx) {
    // 연쇄 호출(Cascading)의 악몽을 지우고, DAO 단에서 UNION ALL을 통해 각각 독립적으로 가져옵니다.
    const [events, eventInstances, eventParticipants, tasks, taskInstances, taskParticipants, specialDays] = await Promise.all([
      SyncDAO.getEventsDeltaFull(pool, ctx),
      SyncDAO.getEventInstancesDeltaFull(pool, ctx), // 부모(events) 참조 없이 독자 검사!
      SyncDAO.getEventParticipantsDeltaFull(pool, ctx),
      SyncDAO.getTasksDeltaFull(pool, ctx),
      SyncDAO.getTaskInstancesDeltaFull(pool, ctx),
      SyncDAO.getTaskParticipantsDeltaFull(pool, ctx),
      SyncDAO.getSpecialDaysDeltaFull(pool, ctx)
    ]);

    return {
      events, event_instances: eventInstances, event_participants: eventParticipants,
      tasks, task_instances: taskInstances, task_participants: taskParticipants, special_days: specialDays
    };
  }

  async _fetchTrackCMessaging(ctx) {
    const messages = await SyncDAO.getMessagesDeltaFull(pool, ctx);

    if (!messages.length) {
      return { messages: [], attachments: [], message_embeds: [], message_reactions: [], message_mentions: [] };
    }

    const messageIds = messages.map(m => m.id);
    const [attachments, embeds, reactions, mentions] = await Promise.all([
      SyncDAO.getMessageAttachments(pool, messageIds, ctx.oldTs),
      SyncDAO.getMessageEmbeds(pool, messageIds, ctx.oldTs),
      SyncDAO.getMessageReactions(pool, messageIds, ctx.oldTs),
      SyncDAO.getMessageMentions(pool, messageIds, ctx.oldTs)
    ]);

    return { messages, attachments, message_embeds: embeds, message_reactions: reactions, message_mentions: mentions };
  }

  async _fetchPersonalData(userId, currDIds, oldTs, msgWindowFrom) {
    const [notifications, activityFeeds, activityFeedCursors, subscriptions, assets, holidayCountries] = await Promise.all([
      SyncDAO.getNotifications(pool, userId, oldTs || msgWindowFrom),
      SyncDAO.getActivityFeedsForSync(pool, currDIds, oldTs),
      SyncDAO.getActivityFeedCursorsForSync(pool, userId, currDIds),
      SyncDAO.getUserSubscriptions(pool, userId, oldTs),
      SyncDAO.getUserAssets(pool, userId, oldTs),
      SyncDAO.getUserHolidayCountries(pool, userId)
    ]);

    let holidays = [];
    if (holidayCountries.length) {
      holidays = await SyncDAO.getHolidays(pool, holidayCountries, oldTs);
    }

    return {
      notifications, activity_feeds: activityFeeds, activity_feed_cursors: activityFeedCursors,
      user_subscriptions: subscriptions, user_assets: assets, holidays
    };
  }

  async syncSettings(userId, settings) {
    return await UserSettingsDAO.updatePartial(pool, userId, settings);
  }

  _buildEmptyResponse(now, currDIds, currCIds) {
    return {
      data: {},
      next_sync_token: SyncToken.encode({ ts: Math.floor(now.getTime() / 1000), d_ids: currDIds, c_ids: currCIds })
    };
  }
}

module.exports = new SyncService();class SyncDAO {

  // =========================================================================
  // 권한 획득 유틸리티
  // =========================================================================
  static async getBinderIdsByUserId(pool, userId) {
    const { rows } = await pool.query(
      `SELECT binder_id FROM binder_members WHERE user_id = $1 AND deleted_at IS NULL`,
      [userId]
    );
    return rows.map(r => r.binder_id);
  }

  static async getSubscribedCalIdsByUserId(pool, userId) {
    const { rows } = await pool.query(
      `SELECT calendar_id FROM calendar_subscriptions WHERE user_id = $1 AND deleted_at IS NULL`,
      [userId]
    );
    return rows.map(r => r.calendar_id);
  }

  // =========================================================================
  // Track A: Meta Data 쿼리 (무조건 100% 최신)
  // =========================================================================
  static async getBindersForSync(pool, currDIds, currCIds) {
    const query = `
      SELECT d.* FROM binders d
      WHERE (
        d.id = ANY($1::uuid[])
        OR d.id IN (SELECT binder_id FROM calendars WHERE id = ANY($2::uuid[]))
      )
      AND d.deleted_at IS NULL
    `;
    const { rows } = await pool.query(query, [currDIds, currCIds]);
    return rows;
  }

  static async getBinderMembers(pool, currDIds) {
    if (!currDIds.length) return [];
    const query = `
      SELECT binder_id, user_id, role, nickname_in_binder, joined_at,
             created_at, updated_at, deleted_at
      FROM binder_members
      WHERE binder_id = ANY($1::uuid[]) AND deleted_at IS NULL
    `;
    const { rows } = await pool.query(query, [currDIds]);
    return rows;
  }

  static async getBinderPreferences(pool, userId, currDIds) {
    if (!currDIds.length) return [];
    const query = `
      SELECT binder_id, user_id, role, nickname_in_binder, notification_level
      FROM binder_members
      WHERE user_id = $1 AND binder_id = ANY($2::uuid[]) AND deleted_at IS NULL
    `;
    const { rows } = await pool.query(query, [userId, currDIds]);
    return rows;
  }

  static async getUsersForSync(pool, currDIds, oldTs) {
    if (!currDIds.length) return [];
    const query = `
      SELECT u.id, ui.user_code, ui.display_name, ui.bio,
             ui.image_url, ui.thumbnail_url,
             u.created_at, ui.updated_at, u.deleted_at
      FROM user_infos ui
      JOIN users u ON ui.user_id = u.id
      WHERE ui.user_id IN (
        SELECT DISTINCT dm.user_id FROM binder_members dm
        WHERE dm.binder_id = ANY($1::uuid[]) AND dm.deleted_at IS NULL
      )
      ${oldTs ? 'AND ui.updated_at > $2' : ''}
    `;
    const params = oldTs ? [currDIds, oldTs] : [currDIds];
    const { rows } = await pool.query(query, params);
    return rows;
  }

  static async getBinderSettings(pool, currDIds) {
    if (!currDIds.length) return [];
    const query = `
      SELECT * FROM binder_settings WHERE binder_id = ANY($1::uuid[])
    `;
    const { rows } = await pool.query(query, [currDIds]);
    return rows;
  }

  static async getSection(pool, currDIds) {
    if (!currDIds.length) return [];
    const query = `
      SELECT * FROM sections WHERE binder_id = ANY($1::uuid[]) AND deleted_at IS NULL
    `;
    const { rows } = await pool.query(query, [currDIds]);
    return rows;
  }

  static async getCalendarsForSync(pool, currDIds, currCIds) {
    const query = `
      SELECT * FROM calendars
      WHERE (binder_id = ANY($1::uuid[]) OR id = ANY($2::uuid[]))
      AND deleted_at IS NULL
    `;
    const { rows } = await pool.query(query, [currDIds, currCIds]);
    return rows;
  }

  static async getSubscribedCalendarRecords(pool, currCIds) {
    if (!currCIds.length) return [];
    const query = `
      SELECT * FROM calendar_subscriptions WHERE calendar_id = ANY($1::uuid[]) AND deleted_at IS NULL
    `;
    const { rows } = await pool.query(query, [currCIds]);
    return rows;
  }

  // =========================================================================
  // Track B: Calendar Data 쿼리 (Delta + Full + Tombstone)
  // =========================================================================
  static async getEventsDeltaFull(pool, ctx) {
    const query = `
      SELECT e.*, es.section_id FROM events e
      LEFT JOIN event_sections es ON es.event_id = e.id
      JOIN calendars c ON e.calendar_id = c.id
      WHERE (c.binder_id = ANY($1::uuid[]) OR e.calendar_id = ANY($2::uuid[]))
        AND e.updated_at > $3

      UNION ALL

      SELECT e.*, es.section_id FROM events e
      LEFT JOIN event_sections es ON es.event_id = e.id
      JOIN calendars c ON e.calendar_id = c.id
      WHERE (c.binder_id = ANY($4::uuid[]) OR e.calendar_id = ANY($5::uuid[]))
        AND e.deleted_at IS NULL
        AND (e.created_at >= $6 OR e.updated_at >= $6)
    `;
    const { rows } = await pool.query(query, [
      ctx.oldDIds, ctx.oldCIds, ctx.oldTs || new Date(0),
      ctx.newDIds, ctx.newCIds, ctx.calWindowFrom
    ]);
    return rows;
  }

  static async getEventInstancesDeltaFull(pool, ctx) {
    const query = `
      SELECT i.* FROM event_instances i
      JOIN events e ON i.event_id = e.id
      JOIN calendars c ON e.calendar_id = c.id
      WHERE (
        ((c.binder_id = ANY($1::uuid[]) OR e.calendar_id = ANY($2::uuid[])) AND i.updated_at > $3)
        OR
        ((c.binder_id = ANY($4::uuid[]) OR e.calendar_id = ANY($5::uuid[])) AND i.deleted_at IS NULL AND i.start_date >= $6)
      )
    `;
    const { rows } = await pool.query(query, [
      ctx.oldDIds, ctx.oldCIds, ctx.oldTs || new Date(0),
      ctx.newDIds, ctx.newCIds, ctx.calWindowFrom
    ]);
    return rows;
  }

  static async getEventParticipantsDeltaFull(pool, ctx) {
    const query = `
      SELECT ep.* FROM event_participants ep
      JOIN event_instances i ON ep.instance_id = i.id
      JOIN events e ON i.event_id = e.id
      JOIN calendars c ON e.calendar_id = c.id
      WHERE (
        ((c.binder_id = ANY($1::uuid[]) OR e.calendar_id = ANY($2::uuid[])) AND ep.updated_at > $3)
        OR
        ((c.binder_id = ANY($4::uuid[]) OR e.calendar_id = ANY($5::uuid[])) AND ep.deleted_at IS NULL)
      )
    `;
    const { rows } = await pool.query(query, [
      ctx.oldDIds, ctx.oldCIds, ctx.oldTs || new Date(0),
      ctx.newDIds, ctx.newCIds
    ]);
    return rows;
  }

  static async getTasksDeltaFull(pool, ctx) {
    const query = `
      SELECT t.* FROM tasks t
      JOIN calendars c ON t.calendar_id = c.id
      WHERE (
        ((c.binder_id = ANY($1::uuid[]) OR t.calendar_id = ANY($2::uuid[])) AND t.updated_at > $3)
        OR
        ((c.binder_id = ANY($4::uuid[]) OR t.calendar_id = ANY($5::uuid[])) AND t.deleted_at IS NULL AND (t.created_at >= $6 OR t.updated_at >= $6))
      )
    `;
    const { rows } = await pool.query(query, [
      ctx.oldDIds, ctx.oldCIds, ctx.oldTs || new Date(0),
      ctx.newDIds, ctx.newCIds, ctx.calWindowFrom
    ]);
    return rows;
  }

  static async getTaskInstancesDeltaFull(pool, ctx) {
    const query = `
      SELECT ti.* FROM task_instances ti
      JOIN tasks t ON ti.task_id = t.id
      JOIN calendars c ON t.calendar_id = c.id
      WHERE (
        ((c.binder_id = ANY($1::uuid[]) OR t.calendar_id = ANY($2::uuid[])) AND ti.updated_at > $3)
        OR
        ((c.binder_id = ANY($4::uuid[]) OR t.calendar_id = ANY($5::uuid[])) AND ti.deleted_at IS NULL AND ti.due_date >= $6)
      )
    `;
    const { rows } = await pool.query(query, [
      ctx.oldDIds, ctx.oldCIds, ctx.oldTs || new Date(0),
      ctx.newDIds, ctx.newCIds, ctx.calWindowFrom
    ]);
    return rows;
  }

  static async getTaskParticipantsDeltaFull(pool, ctx) {
    const query = `
      SELECT tp.* FROM task_participants tp
      JOIN task_instances ti ON tp.instance_id = ti.id
      JOIN tasks t ON ti.task_id = t.id
      JOIN calendars c ON t.calendar_id = c.id
      WHERE (
